package com.procurement.rfq.entity; import com.procurement.vendor.entity.Vendor; import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="rfq_vendors",uniqueConstraints=@UniqueConstraint(columnNames={"rfq_id","vendor_id"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class RfqVendor{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="rfq_vendor_id") private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="rfq_id",nullable=false) private Rfq rfq; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="vendor_id",nullable=false) private Vendor vendor; @Column(name="invitation_date",nullable=false) private LocalDateTime invitationDate; @Enumerated(EnumType.STRING) @Column(name="response_status",nullable=false,length=20) private RfqVendorStatus responseStatus; @Column(name="response_date") private LocalDateTime responseDate; @Column(length=500) private String remarks; @PrePersist void pre(){if(invitationDate==null)invitationDate=LocalDateTime.now();if(responseStatus==null)responseStatus=RfqVendorStatus.INVITED;} }
